package com.fasterxml.jackson.databind.jsontype.impl;

import com.fasterxml.jackson.databind.AnnotationIntrospector;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.MapperConfig;
import com.fasterxml.jackson.databind.cfg.MapperConfig;
import com.fasterxml.jackson.databind.introspect.*;
import com.fasterxml.jackson.databind.introspect.AnnotatedMember;
import com.fasterxml.jackson.databind.introspect.AnnotationIntrospector;
import com.fasterxml.jackson.databind.jsontype.NamedType;
import com.fasterxml.jackson.databind.jsontype.SubtypeResolver;
import java.io.*;
import java.lang.reflect.Modifier;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import java.util.Collection;
import java.util.Collections;
import java.util.List;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

public class StdSubtypeResolver_collectAndResolveSubtypesByTypeId_TriageGen0Test {

    private StdSubtypeResolver resolver;
    private MapperConfig<?> mockConfig;
    private AnnotationIntrospector mockAi;
    private AnnotatedMember mockProperty;
    private JavaType mockBaseType;

    // Test hierarchy classes
    public static class Base {}
    public static class Sub extends Base {}
    public static class Unrelated {}

    @Before
    public void setUp() {
        resolver = new StdSubtypeResolver();
        mockConfig = mock(MapperConfig.class);
        mockAi = mock(AnnotationIntrospector.class);
        mockProperty = mock(AnnotatedMember.class);
        mockBaseType = mock(JavaType.class);

        when(mockConfig.getAnnotationIntrospector()).thenReturn(mockAi);
        when(mockBaseType.getRawClass()).thenReturn(Base.class);
    }

    @Test
    public void testCollectAndResolveSubtypesByTypeId_Minimal() {
        // Test case where no subtypes are found via property or registration
        Collection<NamedType> result = resolver.collectAndResolveSubtypesByTypeId(mockConfig, null, mockBaseType);

        assertNotNull(result);
        // Should at least contain the root type via _combineNamedAndUnnamed
        boolean containsRoot = result.stream().anyMatch(nt -> nt.getType().equals(Base.class));
        assertTrue("Result should contain the base type", containsRoot);
    }

    @Test
    public void testCollectAndResolveSubtypesByTypeId_WithPropertySubtypes() {
        // Mock property returning subtypes via AnnotationIntrospector
        NamedType namedSubtype = new NamedType(Sub.class, "sub");
        when(mockAi.findSubtypes(mockProperty)).thenReturn(Collections.singletonList(namedSubtype));

        Collection<NamedType> result = resolver.collectAndResolveSubtypesByTypeId(mockConfig, mockProperty, mockBaseType);

        assertNotNull(result);
        boolean containsSub = result.stream().anyMatch(nt -> nt.getType().equals(Sub.class));
        assertTrue("Result should contain the subtype found via property", containsSub);
    }

    @Test
    public void testCollectAndResolveSubtypesByTypeId_WithRegisteredSubtypes() {
        // Register a subtype explicitly
        resolver.registerSubtypes(new NamedType(Sub.class, "sub"));

        Collection<NamedType> result = resolver.collectAndResolveSubtypesByTypeId(mockConfig, null, mockBaseType);

        assertNotNull(result);
        boolean containsSub = result.stream().anyMatch(nt -> nt.getType().equals(Sub.class));
        assertTrue("Result should contain the registered subtype", containsSub);
    }

    @Test
    public void testCollectAndResolveSubtypesByTypeId_WithPropertyAndRegisteredSubtypes() {
        // Mix of both
        NamedType propSubtype = new NamedType(Sub.class, "propSub");
        when(mockAi.findSubtypes(mockProperty)).thenReturn(Collections.singletonList(propSubtype));

        resolver.registerSubtypes(new NamedType(Sub.class, "regSub"));

        Collection<NamedType> result = resolver.collectAndResolveSubtypesByTypeId(mockConfig, mockProperty, mockBaseType);

        assertNotNull(result);
        // Check if subtypes are processed (duplicates/names handled by internal map)
        assertTrue(result.size() >= 1);
    }

    @Test
    public void testCollectAndResolveSubtypesByTypeId_FiltersUnrelatedRegisteredSubtypes() {
        // Register a class that is NOT a subtype of Base
        resolver.registerSubtypes(new NamedType(Unrelated.class, "unrelated"));

        Collection<NamedType> result = resolver.collectAndResolveSubtypesByTypeId(mockConfig, null, mockBaseType);

        boolean containsUnrelated = result.stream().anyMatch(nt -> nt.getType().equals(Unrelated.class));
        assertFalse("Should not include unrelated registered subtypes", containsUnrelated);
    }

    @Test
    public void testCollectAndResolveSubtypesByTypeId_PropertyReturnsNull() {
        // Test branch where ai.findSubtypes returns null
        when(mockAi.findSubtypes(mockProperty)).thenReturn(null);

        Collection<NamedType> result = resolver.collectAndResolveSubtypesByTypeId(mockConfig, mockProperty, mockBaseType);

        assertNotNull(result);
        boolean containsSub = result.stream().anyMatch(nt -> nt.getType().equals(Sub.class));
        assertFalse("Should not contain subtypes if AI returns null", containsSub);
    }

    @Test
    public void testCollectAndResolveSubtypesByTypeId_PropertyEmptyList() {
        // Test branch where ai.findSubtypes returns empty collection
        when(mockAi.findSubtypes(mockProperty)).thenReturn(Collections.emptyList());

        Collection<NamedType> result = resolver.collectAndResolveSubtypesByTypeId(mockConfig, mockProperty, mockBaseType);

        assertNotNull(result);
        boolean containsSub = result.stream().anyMatch(nt -> nt.getType().equals(Sub.class));
        assertFalse("Should not contain subtypes if AI returns empty list", containsSub);
    }
}
